[package]
name = "voxfusion-app"
version = "0.1.0"
description = "VoxFusion Desktop Application"
authors = ["you"]
edition = "2024"

[lib]
name = "voxfusion_app_lib"
crate-type = ["staticlib", "cdylib", "rlib"]

[features]
default = []
devtools = ["tauri/devtools"]

[build-dependencies]
tauri-build = { version = "2", features = [] }

[dependencies]
tauri = { version = "2", features = ["macos-private-api", "tray-icon", "image-png"] }
tauri-plugin-opener = "2"
tauri-plugin-single-instance = "2"
tauri-plugin-macos-permissions = "2"
tauri-plugin-clipboard-manager = "2"
serde = { version = "1", features = ["derive"] }
serde_json = "1"
enigo = "0.2"
cpal = "0.15"
hound = "3.5"
chrono = { version = "0.4", features = ["serde"] }
tauri-plugin-store = "2"
tauri-plugin-updater = "2"
tauri-plugin-process = "2"
tauri-plugin-log = "2"
log = "0.4"
whisper-rs = { version = "0.16", features = ["metal"] }
rusqlite = { version = "0.31", features = ["bundled"] }
reqwest = { version = "0.12", features = ["stream"] }
tokio = { version = "1", features = ["full"] }
uuid = { version = "1", features = ["v4"] }
futures-util = "0.3"
plist = "1"
base64 = "0.22"
icns = "0.3"

[target.'cfg(not(any(target_os = "android", target_os = "ios")))'.dependencies]
tauri-plugin-global-shortcut = "2"

[target.'cfg(target_os = "macos")'.dependencies]
core-foundation = "0.10"
core-foundation-sys = "0.8"
objc2 = "0.6"
block2 = "0.6"
objc2-foundation = { version = "0.3", features = ["NSString"] }
objc2-app-kit = { version = "0.3", features = ["NSWorkspace", "NSRunningApplication", "NSEvent", "block2"] }

[profile.release]
strip = true
lto = true
codegen-units = 1
opt-level = "s"
panic = "abort"
overflow-checks = false

[profile.release.package.wry]
debug = false
debug-assertions = false
overflow-checks = false
{
	"$schema": "https://schema.tauri.app/config/2",
	"productName": "VoxFusion",
	"version": "0.3.0",
	"identifier": "io.voxfusion.app",
	"bundle": {
		"active": true,
		"createUpdaterArtifacts": true,
		"targets": ["dmg", "app"],
		"icon": ["icons/icon.icns", "icons/icon.png"],
		"macOS": {
			"entitlements": "entitlements.plist",
			"minimumSystemVersion": "10.15",
			"hardenedRuntime": true,
			"signingIdentity": "Developer ID Application: Egor tokarev (P2M3JQ4DR5)"
		}
	},
	"build": {
		"beforeDevCommand": "vite",
		"devUrl": "http://localhost:1420",
		"beforeBuildCommand": "bun run build",
		"frontendDist": "../dist"
	},
	"app": {
		"macOSPrivateApi": true,
		"withGlobalTauri": false,
		"windows": [
			{
				"label": "main",
				"title": "VoxFusion",
				"width": 1360,
				"height": 850,
				"minWidth": 1024,
				"minHeight": 720,
				"resizable": true,
				"decorations": true,
				"titleBarStyle": "Overlay",
				"hiddenTitle": true,
				"fullscreen": false,
				"center": true
			}
		],
		"security": {
			"csp": null
		}
	},
	"plugins": {
		"opener": {},
		"updater": {
			"endpoints": [
