#[tauri::command]
pub async fn get_frontmost_app() -> Result<Option<FrontmostApp>, String> {
    tokio::task::spawn_blocking(|| {
        let result = panic::catch_unwind(|| {
            use objc2_app_kit::NSWorkspace;

            let workspace = NSWorkspace::sharedWorkspace();
