    let conn = state.conn.lock().map_err(|e| e.to_string())?;
    let mut stmt = conn
        .prepare(
            "SELECT id, domain, word, created_at, updated_at \
             FROM site_dictionary_words \
             ORDER BY domain COLLATE NOCASE ASC, created_at DESC",
        )
        .map_err(|e| e.to_string())?;
    let rows = stmt
        .query_map([], |row| {
