                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
                row.get::<_, String>(4)?,
            ))
        })
        .map_err(|e| e.to_string())?
        .collect::<Result<Vec<_>, _>>()
        .map_err(|e| e.to_string())?;

    let mut grouped: Vec<SiteDictionary> = Vec::new();
    for (id, domain, word, created_at, updated_at) in rows {
        let entry = SiteDictionaryWord {
